{"code":"import arclog,numpy as np
ss=arclog.load();s=ss[-1];b=s.board
print('step',len(ss)-1,s.action,s.levels_completed,s.win_levels,s.state,s.available,'frames',s.frames.shape)
vals,cts=np.unique(b,return_counts=True); print('colors',dict(zip(vals.tolist(),cts.tolist())))
for c in vals:
 objs=arclog.objects(b,colors=int(c),connectivity=4)
 print('color',int(c),'objects',len(objs),[(o.size,o.bbox,tuple(round(v,1) for v in o.centroid),o.hash[:8] if isinstance(o.hash,str) else o.hash) for o in sorted(objs,key=lambda z:-z.size)[:20]])
print('HUD\n',b[:8,:25]); print('bottom',dict(zip(*[a.tolist() for a in np.unique(b[63],return_counts=True)])))
# ringlike
for col in vals:
 found=[]
 for y in range(2,62):
  for x in range(2,62):
   w=b[y-2:y+3,x-2:x+3]
   if np.sum(w==col)>=20 and b[y,x]!=col:found.append((x,y,int(b[y,x]),int(np.sum(w==col))))
 if found:print('ringlike',int(col),found[:20])
# center grids likely same centers
xs=list(range(10,53,6));ys=list(range(10,53,6))
print('center colors')
print('   '+' '.join(f'{x:2}' for x in xs))
for y in ys:print(f'{y:2}',' '.join(f'{int(b[y,x]):2}' for x in xs))
","timeout":30}

